-- Independent educational prose; all ministry/source matching is pending.
DO $dadyoom$
DECLARE r RECORD; target_id uuid; prior text; nact integer; hasprogress integer;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"d3dc9746-4f1f-472c-8947-e614e7d06390","n":1,"title":"كيف تكتب بحثًا","passage":"يحتاج البحث إلى سؤال واضح وخطة لجمع المصادر وتمييز المعلومات من الآراء وتوثيق الاستشهادات، ثم مناقشة النتائج والحدود دون نسخ الفقرات. في مثال أصلي يقارن طالب تاريخين لنشر دراسة ويختار أحدث مصدر موثوق.","question":"ما الذي يسبق جمع مادة البحث؟","correct":"تحديد سؤال وخطة واضحة","wrong":["اختيار خاتمة مسبقة","نسخ أول نتيجة","إلغاء المصادر"],"practice":"ضع خطة بحث مدرسية من سؤال وثلاث خطوات ومصدرين ومعيار تحقق.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"d3dc9746-4f1f-472c-8947-e614e7d06390","n":2,"title":"الحوار الصحفي","passage":"يعتمد الحوار الصحفي على تحضير أسئلة مناسبة واحترام الضيف وتسجيل الإجابات بدقة، ثم تحريرها دون تغيير المعنى أو اختلاق اقتباس. في مثال مستقل يجري طالب حوارًا مع أمين مكتبة حول تنظيم الاستعارة ويطلب إذنًا قبل النشر.","question":"ما الذي يضمن أمانة نقل إجابة الضيف؟","correct":"التوثيق والتأكد من الصياغة والموافقة","wrong":["اختلاق قول مؤثر","حذف السياق عمدًا","نسبة رأي للمحاور"],"practice":"صمم خمس أسئلة صحفية لمتحدث افتراضي واشرح هدف كل سؤال.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"d3dc9746-4f1f-472c-8947-e614e7d06390","n":3,"title":"كتابة القصة","passage":"تبدأ القصة بشخصية وغاية، ويظهر عائق فتتطور المحاولات إلى نتيجة معقولة. مثال مستقل يفقد طالب مفتاح خزانة أدوات ثم يراجع الأماكن التي مر بها ويجده بإبلاغ المسؤول؛ النهاية ترتبط بالفعل لا بالمصادفة البعيدة.","question":"ما الذي يجعل حل العقدة مقنعًا في المثال؟","correct":"اعتماد الحل على تصرفات الشخصية","wrong":["ظهور حل بلا سبب","حذف المشكلة","تبديل اسم القصة"],"practice":"اكتب قصة قصيرة ذات بداية وعقدة ومحاولة وحل منطقية.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"d3dc9746-4f1f-472c-8947-e614e7d06390","n":4,"title":"الاستدلال","passage":"يقوم الاستدلال على مقدمات وشواهد تدعم النتيجة، ويتطلب التمييز بين الدليل والاحتمال والمغالطة. في مثال أصلي يرى طالب أن تنظيم المكتبة ساعد على الوصول للكتب، لكنه لا يستنتج نسبة تحسن عامة من واقعة واحدة.","question":"ما شرط الاستنتاج السليم؟","correct":"أن تدعمه مقدمات وشواهد مناسبة","wrong":["أن يكون رأيًا شائعًا","أن يعتمد على العنوان","أن يخلو من قيود"],"practice":"حلل حجتين متعارضتين في موضوع مدرسي وحدد قوة الأدلة وحدودها.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"d3dc9746-4f1f-472c-8947-e614e7d06390","n":5,"title":"الحوار حول قضية (الاستنساخ)","passage":"عند مناقشة الاستنساخ يجب التفريق بين المفاهيم العلمية والاستعمالات الأخلاقية والقانونية دون وصف خطوات تقنية حساسة أو نسب موقف إلى النص المقرر بلا مصدر. في حوار مستقل يسأل طالبان عن حدود الأدلة ويستمعان لرأي خبير.","question":"ما الذي يجعل الحوار العلمي حول قضية خلافية مسؤولًا؟","correct":"تحديد المصطلح وفحص الأدلة والاعتبارات الأخلاقية","wrong":["الخلط بين المفاهيم","إلغاء الآراء ذات الصلة","اختلاق نتيجة"],"practice":"صمم حوارًا يطرح ثلاث أسئلة تحقق وأخلاقيات مناسبة حول قضية علمية.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"d3dc9746-4f1f-472c-8947-e614e7d06390","n":6,"title":"التخطيط","passage":"التخطيط تحديد هدف وأنشطة وأولويات وموارد ومواعيد ثم متابعة ما تحقق. في نموذج مستقل يضع فريق موعدًا لمشروع القراءة ويخصص وقتًا احتياطيًا للمراجعة وقياس النتائج بدل افتراض النجاح.","question":"ما الذي يجعل الخطة قابلة للمتابعة؟","correct":"مواعيد وأدوار ومؤشرات واضحة","wrong":["شعار غير محدد","غياب المسؤول","إلغاء التقييم"],"practice":"أنشئ خطة مشروع صغير مع مهمة لكل عضو ومؤشر إنجاز.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"d3dc9746-4f1f-472c-8947-e614e7d06390","n":7,"title":"محاضر الاجتماعات","passage":"يذكر محضر الاجتماع التاريخ والحاضرين والموضوعات والقرارات والمسؤوليات والمواعيد، ويجب أن يفصل القرار الفعلي عن مجرد اقتراح. في نموذج مستقل توافق مجموعة على جدول استعارة، ويسجل الكاتب النتيجة دون إضافة تصويت لم يحدث.","question":"ما الذي يميّز القرار من المقترح في المحضر؟","correct":"توثيق ما تم الاتفاق عليه بالفعل","wrong":["صياغة رأي شخصي بوصفه قرارًا","إخفاء الحضور","تغيير الزمن"],"practice":"اكتب محضر اجتماع افتراضيًا واضح البنود والقرارات والمسؤوليات.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"d3dc9746-4f1f-472c-8947-e614e7d06390","n":8,"title":"البرهنة (رهانات المستقبل)","passage":"تحتاج مناقشة قضية مستقبلية إلى فصل ما تؤيده بيانات حالية من سيناريو محتمل، وتدعيم الفرضية بمقدمات وحدود، لا تحويل التوقع إلى يقين. في مثال مستقل يناقش فريق استعمال أداة تعليمية مستقبلًا ويحدد مؤشرات قبل اتخاذ قرار.","question":"ما العنصر الذي يحمي البرهنة المستقبلية من المبالغة؟","correct":"توضيح الفرضيات ومصدر التوقع وحدوده","wrong":["الجزم بنتيجة لا دليل عليها","الاعتماد على شعار","إلغاء البدائل"],"practice":"اكتب برهنة قصيرة حول اختيار تقني مستقبلي بدليلين وتحفظ.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"a5204ec7-75c5-4b01-a1bd-3763e6f291e7","n":1,"title":"قضية الشعر الجديد","passage":"تتصل قضية الشعر الجديد بتحولات بناء القصيدة والإيقاع والصورة واللغة، لكنها لا تعني أن كل نص حديث يرفض الوزن؛ ينبغي تحليل نماذج شعرية موثقة ومقارنة أشكالها دون تعميم.","question":"ما الذي يفيد في الحكم على تجديد قصيدة؟","correct":"تحليل البناء والإيقاع والصورة ضمن سياق","wrong":["تاريخ الطباعة فقط","اسم الشاعر وحده","عدد الأسطر وحده"],"practice":"قارن مقطعًا عموديًا ومقطع تفعيلة صحيحَي المصدر في خصيصتين فنيتين.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"a5204ec7-75c5-4b01-a1bd-3763e6f291e7","n":2,"title":"أنشودة المطر","passage":"تستلزم دراسة «أنشودة المطر» لبدر شاكر السياب الأبيات المقررة لفهم الصورة والإيقاع ودلالة المطر، ولا يجوز اختلاق بيت على لسانه. مثال أصلي يراقب متعلم المطر ويتذكر موسمًا قديمًا، وهو ليس من القصيدة.","question":"ما الذي يحدد دلالة المطر في النص الشعري؟","correct":"الأبيات الصحيحة وسياق تكرار الصورة","wrong":["عنوان القصيدة وحده","بيت مولد","تخمين حادثة"],"practice":"وثق صورة صحيحة من «أنشودة المطر» وحللها مع إيقاع المقطع.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"a5204ec7-75c5-4b01-a1bd-3763e6f291e7","n":3,"title":"قصيدة حب إلى مطرح","passage":"لا يجوز نسبة صور مكانية أو أبيات إلى قصيدة «حب إلى مطرح» قبل الرجوع إلى النص المدرسي الموثق ومعرفة قائله. في مشهد مستقل يتذكر مسافر حيًا بحريًا فيكتب وصفًا لارتباط المكان بالذاكرة دون أن يمثل القصيدة.","question":"ما الدليل على عاطفة الشاعر نحو المكان؟","correct":"شواهد لفظية وصور من النص الأصلي","wrong":["العنوان فقط","حكاية من إنشاء الطالب","قافية متخيلة"],"practice":"استخرج وصفًا صحيحًا من القصيدة وناقش علاقته بالمكان والانفعال.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"d3dcec03-da94-4a9f-86c9-8018739b6c02","n":1,"title":"أدب السيرة الذاتية","passage":"تعرض السيرة الذاتية تجربة يرويها صاحبها من منظور الذاكرة، وقد يختار ترتيب الوقائع وتأمل أثرها؛ لا تعني الدقة الأدبية الاستغناء عن التوثيق عند الإشارة لأحداث تاريخية. في نموذج مستقل يكتب طالب تجربته مع تعلم القراءة.","question":"ما الذي يميز صوت الراوي في السيرة الذاتية؟","correct":"ارتباطه بتجربة يرويها عن نفسه","wrong":["كونه راويا عليما دائما","غياب الزمن","عدم وجود شخصيات"],"practice":"اكتب ذكرى شخصية آمنة في فقرة وميّز الحدث من الانطباع.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"d3dcec03-da94-4a9f-86c9-8018739b6c02","n":2,"title":"عهد الطفولة","passage":"عنوان «عهد الطفولة» لا يحدد المؤلف أو الأحداث أو النص المعتمد دون قراءة المقرر؛ وأي تفاصيل يختلقها ضاديوم لا يجوز أن تنسب لصاحب العمل. في مثال مستقل يتذكر راوي طريقه إلى المدرسة الأولى ويفسر أثر المكان في ذاكرته.","question":"ما الذي يثبت دلالة حدث من مرحلة الطفولة في نص؟","correct":"شاهد موثق من السيرة وسياقه","wrong":["تخمين من العنوان","حكاية غير منسوبة","إضافة قول للمؤلف"],"practice":"اقرأ المقطع المدرسي الصحيح واستخرج ذكرى وصورة مع تحليل.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"d3dcec03-da94-4a9f-86c9-8018739b6c02","n":3,"title":"مغامر عُماني في أدغال إفريقيا","passage":"يحتاج نص «مغامر عُماني في أدغال إفريقيا» إلى المصدر الحقيقي قبل نسبة رحلة أو تواريخ أو حوادث لمغامر بعينه. في قصة مستقلة يراجع رحّالة أدواته وخريطة مساره قبل رحلة استكشافية آمنة، دون الادعاء أنها جزء من النص.","question":"ما الشرط اللازم للتحقق من رواية رحلة تاريخية؟","correct":"مصدر موثق وتفاصيل زمنية ومكانية","wrong":["عنوان مثير وحده","خريطة غير مؤرخة","سرد مبتكر"],"practice":"حلل النص المدرسي واستخرج حدثًا صحيحًا يوضح شخصية الراوي.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"30b392c9-b306-4221-88cd-e08955cbeae8","n":1,"title":"الأدب المسرحي","passage":"يبنى النص المسرحي على الحوار والأفعال والتوتر الدرامي وإرشادات الأداء، وتؤثر الإضاءة والحركة في استجابة المتلقي. في مثال مستقل تختلف شخصيتان حول تنظيم نشاط ثم تتفقان بعد تبادل الحجج.","question":"ما الذي يكشف تطور الصراع الدرامي؟","correct":"الحوار وتغير قرارات الشخصيات","wrong":["عدد صفحات النص","وزن القصيدة","اسم المسرح"],"practice":"حوّل فقرة قصصية من إنشائك إلى مشهد حواري مع إرشادات.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"30b392c9-b306-4221-88cd-e08955cbeae8","n":2,"title":"كم لبثنا في الكهف؟","passage":"يحتاج نص «كم لبثنا في الكهف؟» إلى مصدره الأدبي الأصلي حتى لا يختلط بالحكاية القرآنية أو بأعمال مسرحية أخرى؛ ولا يجوز اختلاق حوار ديني أو تحريف رواية. مثال مستقل يناقش متعلمون معنى تغير الزمن في قصة متخيلة.","question":"ما الذي يحمي تحليل هذا النص من الخلط بين المصادر؟","correct":"التثبت من المؤلف والنص والسياق","wrong":["تشابه العنوان وحده","اختراع حوار","الخلط بحكاية أخرى"],"practice":"اقرأ النسخة المقررة واستخرج سؤالًا مسرحيًا مع تفسير وظيفته.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"570861a4-e0d1-4f61-a097-7939d4615cd9","n":1,"title":"حوار الترجمة الأدبية ومشكلاتها","passage":"تتطلب الترجمة الأدبية الموازنة بين معنى النص الأصلي وإيقاعه وصوره وسياقه الثقافي، ولا تُفترض ترجمة حرفية ناجحة لكل استعارة. في تدريب مستقل تقارن طالبة طريقتين لترجمة عبارة مجازية من نص مأذون وتشرح أثر كل خيار.","question":"ما التحدي الذي يميز ترجمة صورة أدبية؟","correct":"نقل المعنى والأثر مع مراعاة السياق","wrong":["استبدال الكلمات عشوائيًا","حذف الصورة دائمًا","إهمال النص الأصلي"],"practice":"قارن ترجمتين مأذونتين لمقطع قصير وحلل الدقة والأثر.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"570861a4-e0d1-4f61-a097-7939d4615cd9","n":2,"title":"الصحراء العربية","passage":"يتطلب نص «الصحراء العربية» المترجم معرفة المؤلف الأصلي والمترجم وسياق النص، ولا يجوز نسبة فقرة من ضاديوم إلى أحدهما. في مثال أصلي يصف راو اتساع الصحراء واختلاف الضوء عند المغيب، ويستخدم لتحليل الصورة فقط.","question":"ما الذي يلزم لتوثيق نص أدبي مترجم؟","correct":"اسم المؤلف والمترجم والمصدر المعتمد","wrong":["العنوان وحده","عبارة مبتكرة","البلد فقط"],"practice":"استخرج من النص المترجم المقرر صورة وناقش أثر الاختيار اللغوي.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"f8f3fea1-0296-45a8-8bda-8d133df5411b","n":1,"title":"القصة","passage":"تُبنى القصة من حدث وشخصيات وعقدة وتحول وزاوية سرد مناسبة، ولا يلزم أن تنتهي جميع القصص بحل سعيد. في مشهد مستقل تنسى طالبة موعد لقاء ثم تصحح تنظيم وقتها؛ الناتج يرتبط باختيار الشخصية.","question":"ما العنصر الذي ربط نهاية المشهد بأحداثه؟","correct":"تغير قرار الشخصية بعد المشكلة","wrong":["مصادفة بلا سبب","قافية نثرية","حذف الهدف"],"practice":"خطط لقصة قصيرة من ثلاثة مشاهد وعقدة وحل.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"f8f3fea1-0296-45a8-8bda-8d133df5411b","n":2,"title":"اليوم الجديد","passage":"عنوان «اليوم الجديد» لا يثبت شخصية أو نهاية النص المدرسي أو مؤلفه؛ نحتاج قراءته قبل تلخيصه. في مثال مستقل يراجع شخص قراره في بداية يوم مختلف ويرتب أولوياته، وهو تدريب قصصي لا اقتباس.","question":"ما الذي يجب قراءته لتحديد نقطة التحول في النص؟","correct":"الأحداث والحوار الأصليان","wrong":["العنوان فقط","حكاية أخرى","افتراض نهاية"],"practice":"استخرج من النص المقرر قرارًا غيّر مجرى الحدث مع شاهد موثق.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"f8f3fea1-0296-45a8-8bda-8d133df5411b","n":3,"title":"زمن الفقر","passage":"قد يتناول النص السردي «زمن الفقر» علاقة الشخصيات بظروف اقتصادية واجتماعية، لكن لا يصح تخمين أحداثه أو تعميم تجربة شخص واحد على مجتمع كامل. مثال مستقل تتعاون أسرة على تخطيط نفقاتها دون وصم المحتاجين.","question":"ما الممارسة المتزنة عند قراءة قصة اجتماعية؟","correct":"تحليل ظروف الشخصيات مع مراعاة السياق","wrong":["اتهام كل فقير","تعميم حالة واحدة","اختلاق أرقام"],"practice":"حلل وصفًا اجتماعيًا موثقًا في النص المقرر وميّز حدث القصة من حكمك الشخصي.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"5e46020d-6375-4d86-be90-4ba4a80c3c8b","n":1,"title":"حوار الشعوب","passage":"قد يساعد حوار الشعوب على تبادل المعرفة وفهم اختلاف التجارب عندما يستند إلى احترام اللغة والمعتقد والحقوق وتجنب الصور النمطية. في مثال مستقل يعمل طلاب من بلدين على قراءة قصة ويشرح كل منهم مفردات محلية.","question":"ما السلوك الأساسي لحوار مثمر؟","correct":"الإنصات والتفسير دون تعميم","wrong":["السخرية من اللغة","إخفاء وجهة النظر","الحكم على الجميع"],"practice":"اكتب حوارًا بين ثقافتين حول موضوع تعليمي مع سؤال وتوضيح متبادل.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"5e46020d-6375-4d86-be90-4ba4a80c3c8b","n":2,"title":"شجرة التواصل الحضاري: مسيرة الخير 1995","passage":"يحمل النص عنوانًا مرتبطًا بسنة 1995 لكن لا يجوز اختلاق وقائع الرحلة أو الأشخاص أو المؤسسات التي يذكرها؛ يحتاج التحليل إلى مصدره الصحيح. في تدريب مستقل يرسم طلاب مخططًا لتبادل الخبرات بين مدارس مع توثيق كل معلومة.","question":"ما الذي يمنع إضافة روايات تاريخية غير صحيحة؟","correct":"الرجوع إلى النص ومصدره وتاريخه","wrong":["تخمين أحداث عام 1995","الاعتماد على عنوان","اختراع اقتباس"],"practice":"استخرج من النص المدرسي معلومة موثقة عن التواصل الحضاري وبيّن دلالتها.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"5e46020d-6375-4d86-be90-4ba4a80c3c8b","n":3,"title":"الشباب ووقت الفراغ","passage":"يمكن إدارة وقت الفراغ بأنشطة تناسب اهتمامات الشباب وظروفهم وتتوازن مع الراحة والمسؤوليات. في مثال مستقل يختار طالب القراءة والرياضة والتطوع حسب جدول واقعي ويخصص وقتًا غير مخطط للطوارئ.","question":"ما الذي يجعل خطة وقت الفراغ واقعية؟","correct":"التوازن بين الاهتمامات والراحة والواجبات","wrong":["إلغاء الراحة","ملء كل دقيقة","نسخ جدول الآخر"],"practice":"اكتب خطة أسبوعية متوازنة ثم فسر معيار تقييمها.","old":"DADYOOM_OM_G12_MUUNIS_S2"},{"cid":"2a98ce35-976e-4ad3-8b37-d05de0953327","unit":"5e46020d-6375-4d86-be90-4ba4a80c3c8b","n":4,"title":"السينما والأدب","passage":"قد تنقل السينما عملًا أدبيًا بإعادة بناء الشخصيات والمشاهد والزمان، لكنها ليست نسخة حرفية من النص؛ تُقارن القصة الأصلية بالاختيارات السينمائية من حيث الراوي والحوار والصورة.","question":"ما الفارق الأساسي بين الوسيطين في السرد؟","correct":"اعتماد السينما على الصورة والصوت إلى جانب الحوار","wrong":["كون السينما بلا قصة","تطابق كل تفاصيلها","غياب الشخصيات في الأدب"],"practice":"قارن فقرة مأذونة ومشهدًا مقتبسًا مع تفسير اختلاف التعبير.","old":"DADYOOM_OM_G12_MUUNIS_S2"}]'::jsonb)
 AS x(cid uuid,unit uuid,n integer,title text,passage text,question text,correct text,wrong text[],practice text,old text)
 LOOP
  SELECT l.id,l.content INTO STRICT target_id,prior
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
  JOIN public.grades g ON g.id=u.grade_id
  JOIN public.curricula c ON c.id=g.curriculum_id
  JOIN public.countries co ON co.id=c.country_id
  WHERE co.code='OM' AND c.id=r.cid
    AND g.grade_number=12 AND u.semester=2 AND u.id=r.unit
    AND l.sort_order=r.n AND l.title=r.title AND l.status='published'
  FOR UPDATE OF l;

  SELECT count(*) INTO hasprogress FROM public.student_lesson_progress WHERE lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'OM_G12_MUUNIS_HAS_PROGRESS_%',r.title; END IF;
  SELECT count(*) INTO hasprogress FROM public.lesson_activity_attempts att
    JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'OM_G12_MUUNIS_HAS_ATTEMPTS_%',r.title; END IF;
  IF char_length(coalesce(prior,''))>=350 THEN RAISE EXCEPTION 'OM_G12_MUUNIS_ALREADY_CONTENT_%',r.title; END IF;
  SELECT count(*) INTO nact FROM public.lesson_activities
    WHERE lesson_id=target_id AND content->>'origin'=r.old AND answer='{}'::jsonb;
  IF nact<>3 THEN RAISE EXCEPTION 'OM_G12_MUUNIS_EXPECTED_3_PLACEHOLDERS_%',r.title; END IF;

  UPDATE public.lessons SET
    content='ضاديوم — إثراء تعليمي أصلي للسنة الرابعة الإعدادية في موريتانيا. هذا ليس نص الكتاب المعتمد ولا تأكيدًا لمطابقة جميع الفصول؛ الاسم مستورد ويلزم تحقق وزاري.'
    ||E'\n\n'||'عنوان الدرس: '||r.title
    ||E'\n\n'||'هدف التعلم: أن يشرح المتعلم فكرة أو قاعدة من المجال، ويحلل قرينة أو شاهدًا صحيح النسبة، ويكتب استجابة جديدة تستند إلى دليل.'
    ||E'\n\n'||'شرح وتطبيق أصلي: '||r.passage
    ||E'\n\n'||'سؤال فهم: '||r.question
    ||E'\n\n'||'تطبيق كتابي مستقل: '||r.practice
    ||E'\n\n'||'التمايز: دعم بقائمة مفردات وخطوات تحليل أساسية، ومستوى متوسط يبرر الاختيار، ومستوى متقدم يقارن بين تفسيرين أو يختبر دقة المصدر. يتولى المعلم مراجعة مهام الكتابة.'
    ||E'\n\n'||'تحذير المصدر: لا تُنسب أمثلة ضاديوم إلى شاعر أو مؤرخ أو نص ديني؛ راجع المصدر المعتمد أولًا.'
    ||E'\n\n'||'المحتوى السابق المحفوظ: '||coalesce(prior,''),
    updated_at=now() WHERE id=target_id;

  UPDATE public.lesson_activities SET
    prompt='اقرأ النص التدريبي المستقل، واستخرج منه الفكرة أو الشاهد الذي تستند إليه الإجابة.',
    content=content||jsonb_build_object('origin','DADYOOM_OM_G12_T2_MUUNIS_ORIGINAL_25_20261009','previousOrigin',r.old,
      'text',r.passage,'notOfficialBook',true,'sourceVerification','pending')
    WHERE lesson_id=target_id AND activity_type='reading'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.question,
    content=content||jsonb_build_object('origin','DADYOOM_OM_G12_T2_MUUNIS_ORIGINAL_25_20261009','previousOrigin',r.old,
       'text',r.question,'notOfficialBook',true,'sourceVerification','pending',
       'options',CASE (r.n%4)
       WHEN 0 THEN jsonb_build_array(r.correct,r.wrong[1],r.wrong[2],r.wrong[3])
       WHEN 1 THEN jsonb_build_array(r.wrong[1],r.correct,r.wrong[2],r.wrong[3])
       WHEN 2 THEN jsonb_build_array(r.wrong[1],r.wrong[2],r.correct,r.wrong[3])
       ELSE jsonb_build_array(r.wrong[1],r.wrong[2],r.wrong[3],r.correct) END),
    answer=jsonb_build_object('correct',r.correct)
    WHERE lesson_id=target_id AND activity_type='multiple_choice'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.practice,
    content=content||jsonb_build_object('origin','DADYOOM_OM_G12_T2_MUUNIS_ORIGINAL_25_20261009','previousOrigin',r.old,
     'text',r.practice,'notOfficialBook',true,'sourceVerification','pending',
     'humanReviewRequired',true)
    WHERE lesson_id=target_id AND activity_type='writing'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  SELECT count(*) INTO nact FROM public.lesson_activities
   WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_OM_G12_T2_MUUNIS_ORIGINAL_25_20261009';
  IF nact<>3 THEN RAISE EXCEPTION 'OM_G12_MUUNIS_ACTIVITY_UPDATE_FAILED_%',r.title; END IF;
 END LOOP;
END $dadyoom$;